import React from 'react';
import { User } from 'lucide-react';

const ProfileCard = () => {
  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50">
      <div className="text-center">
        <div className="h-20 w-20 rounded-full bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center mx-auto mb-4">
          <User className="h-10 w-10 text-white" />
        </div>
        <h3 className="font-bold text-neutral-900 dark:text-white">Enzo Admin</h3>
        <p className="text-sm text-neutral-600 dark:text-neutral-400 mb-4">enzo@gmail.com</p>
        <button className="w-full py-2.5 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-medium hover:from-primary-600 hover:to-secondary-600 transition-all duration-300">
          Modifier le profil
        </button>
      </div>
    </div>
  );
};

export default ProfileCard;
